import { redirect, fail } from "@sveltejs/kit";
import { deletePost } from "../../../../../../chunks/database.js";
const actions = {
  default: async ({ params }) => {
    const id = parseInt(params.id);
    try {
      await deletePost(id);
      throw redirect(303, "/admin/posts");
    } catch (error) {
      if (error.status === 303) {
        throw error;
      }
      return fail(500, { error: "Erro ao excluir post" });
    }
  }
};
export {
  actions
};
